# ─── Classes ────────────────────────────────────────────────────────────────


class Priority(enum.Enum):
    NORMAL = 0
    HIGH = 1
    EXTREME = 2


class Status(enum.Enum):
    PENDING = "pending"
    RUNNING = "running"
    DONE = "done"
    FAILED = "failed"


def fail() -> None:
    raise ValueError()


def require(condition: bool, msg: str | None = None) -> None:
    if not condition:
        raise AssertionError(msg or "")


